import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Übersicht","description":"","frontmatter":{"title":"Übersicht"},"headers":[],"relativePath":"projects/uix/index.md","filePath":"projects/uix/index.md","lastUpdated":1792754181000}'),a={name:"projects/uix/index.md"};function s(o,e,l,d,u,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-extension-fur-home-assistant" tabindex="-1">UI eXtension für Home Assistant <a class="header-anchor" href="#ui-extension-fur-home-assistant" aria-label="Permalink to &quot;UI eXtension für Home Assistant&quot;">​</a></h1><blockquote><p><strong>Unabhängige Übersetzung</strong> Diese Dokumentation ist eine unabhängige deutsche Übersetzung und wird von UGSo Software gepflegt. Sie ist nicht die offizielle Dokumentation des UIX-Projekts. Maßgeblich bleibt die englische Originaldokumentation unter <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">https://uix.lf.technology/</a>.</p><p>Basis: GitHub-Release <a href="https://github.com/Lint-Free-Technology/uix/releases/tag/v8.4.0" target="_blank" rel="noreferrer"><code>v8.4.0</code></a> vom 07.10.2026. Benötigt <strong>Home Assistant 2026.10.0 oder neuer</strong>. Original-Repository <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, Release-Stand <a href="https://github.com/Lint-Free-Technology/uix/commit/71b8ccd38202257c070ae9970a7aac12a68a6389" target="_blank" rel="noreferrer"><code>71b8ccd</code></a>. Die Übersetzungen wurden mit dem bis zu diesem Release abgeglichenen Dokumentationsstand geprüft. Einzelheiten und bekannte Grenzen stehen im <a href="./translation-status">Übersetzungsstatus</a>.</p><p>Vielen Dank an das UIX-Projekt für die durchdachte Umsetzung und die sehr gute englische Originaldokumentation, auf der diese deutsche Arbeitsfassung basiert.</p><p>Die originale UIX-Dokumentation ist von <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a> und steht unter <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Code des UIX-Projekts bleibt separat unter MIT lizenziert.</p></blockquote><p><img src="https://raw.githubusercontent.com/Lint-Free-Technology/uix/f9eb8fa571dbce6cd771c53ca11dcf2401c8a933/docs/source/assets/images/mixed.png" alt="UIX Logo"></p><h2 id="was-ist-ui-extension" tabindex="-1">Was ist UI eXtension? <a class="header-anchor" href="#was-ist-ui-extension" aria-label="Permalink to &quot;Was ist UI eXtension?&quot;">​</a></h2><blockquote><p><strong>Für Card-mod-Nutzer</strong> Wenn du von Card-mod wechselst, lies zuerst die <a href="./faq">FAQ</a>. Dort sind die wichtigsten Unterschiede, Migrationspunkte und typischen Stolperstellen zusammengefasst.</p></blockquote><p>UI eXtension, kurz UIX, ist eine Home-Assistant-Integration für Anpassungen an der Oberfläche. Sie erweitert Karten, Zeilen, Badges, Dialoge und andere Frontend-Elemente mit CSS, Templates und zusätzlichen UI-Verhalten.</p><p>UIX besteht aus drei großen Bereichen:</p><ul><li><a href="./using/index">UIX Styling</a> für CSS-Anpassungen an Home-Assistant-Frontend-Elementen.</li><li><a href="./forge/index">UIX Forge</a> für dynamisch erzeugte Elemente, wiederverwendbare Vorlagen und erweiterte Sparks.</li><li><a href="./broker/index">UIX Broker</a> für deklarative Interaktionen: Browser-Events, Tastenkürzel und Home-Assistant-Events wählen ein Element aus, prüfen Regeln und führen Direktiven in ihrer Reihenfolge aus.</li></ul><h2 id="neu-in-uix-8-4-0" tabindex="-1">Neu in UIX 8.4.0 <a class="header-anchor" href="#neu-in-uix-8-4-0" aria-label="Permalink to &quot;Neu in UIX 8.4.0&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Gesamtprüfung vom 22.10.2026</p><p>Alle 64 Originalseiten wurden mit <code>dev</code>-Revision <strong>26e54e6 / 9.0.0-beta.2</strong> abgeglichen. EN enthält jetzt die vollständigen Originaltexte; DE/FR ergänzen fehlende Inhalte und korrigierte Beispiele. Die stabile Basis bleibt 8.4.0. Umfang und Nachweise stehen im <a href="./translation-status">Übersetzungsstatus</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Vorschau separat abgeglichen</p><p>Die Änderungen auf <code>dev</code> bis <strong>9.0.0-beta.0</strong> wurden am 09.10.2026 in DE/FR übernommen. Die <a href="./forge/forge#layered-configuration">geschichtete Forge-Konfiguration</a> und das neue Verhalten beim Update vor einem Home-Assistant-Neustart sind Vorschaufunktionen. Die stabile Basis bleibt 8.4.0. Details im <a href="./translation-status">Übersetzungsstatus</a>.</p></div><ul><li><a href="./forge/sparks/form">Form Spark</a> und <a href="./extras/uix-actions#popover">Popover-Aktion</a> für Formulare und eingeblendete Inhalte.</li><li><a href="./extras/style-frame-panels">Frame-Panels stylen</a> mit interner Frame-Laufzeit; diese experimentelle Option bleibt standardmäßig deaktiviert.</li><li><a href="./using/themes">Theme-Schriften mit <code>uix-fonts</code></a> und <a href="./using/images">Entitätsbilder in Kartenübersichten</a>, einschließlich der Anpassung an Home Assistant 2026.10.</li><li><a href="./broker/directives#direktiven-regeln">Broker-Direktiven-Regeln</a> können Ergebnisse früherer JavaScript- oder Template-Direktiven verwenden.</li></ul><p>Die zuvor beschriebenen 8.4-Beta-Ergänzungen gehören damit zur stabilen Version. Historische Versionshinweise kennzeichnen weiterhin die Einführung einzelner Funktionen.</p><h2 id="schnell-loslegen" tabindex="-1">Schnell loslegen <a class="header-anchor" href="#schnell-loslegen" aria-label="Permalink to &quot;Schnell loslegen&quot;">​</a></h2><p>Der beste Einstieg ist der <a href="./quick-start">Schnellstart</a>. Dort findest du Installation, Einrichtung als Home-Assistant-Dienst und je ein erstes Beispiel für UIX Styling und UIX Forge.</p><h2 id="wichtige-bereiche" tabindex="-1">Wichtige Bereiche <a class="header-anchor" href="#wichtige-bereiche" aria-label="Permalink to &quot;Wichtige Bereiche&quot;">​</a></h2><ul><li><a href="./using/index">UIX Styling verwenden</a></li><li><a href="./forge/index">UIX Forge verwenden</a></li><li><a href="./broker/index">UIX Broker verwenden</a></li><li><a href="./concepts/index">Konzepte verstehen</a></li><li><a href="./debugging/index">Debugging</a></li><li><a href="./faq">FAQ</a></li></ul><blockquote><p><strong>Stand dieser deutschen Doku</strong> Am 08.10.2026 mit dem Dokumentationsstand von UIX <code>8.4.0</code> abgeglichen. Bei Unklarheiten gilt immer die englische Originaldokumentation.</p></blockquote>',18)])])}const f=n(a,[["render",s]]);export{g as __pageData,f as default};
